"""Apply exact reviewed 9G1–9G8 proposals sequentially; preserve all other records."""
import argparse
import copy
import hashlib
import json
from pathlib import Path
from compile_curriculum import Emitter, kotlin_string
from content_schema import Schema
ROOT=Path(__file__).resolve().parents[1]
BASE=Path('docs/curriculum/app-migration/implementation-evidence/9G')
ACTIONS=Path('docs/curriculum/app-migration/question-actions.json')
BANK=Path('composeApp/src/commonMain/kotlin/se/korkort/Bank.kt')
IDS=['situation-'+s for s in ['032','045','105','107','125','162','172','178']]
def read(p):return json.loads((ROOT/p).read_text())
def dump(v):return json.dumps(v,ensure_ascii=False,indent=2)+'\n'
def origin(p,locator):return {'file':{'path':str(p),'sha256':hashlib.sha256((ROOT/p).read_bytes()).hexdigest()},'locator':locator,'evidence_ids':[],'pdf_evidence_page':None}
def rich(s):return [{'type':'text','text':s}]
def outputs():
 bank=read(Path('content/questions.json')); actions=read(ACTIONS)['questions']; mapping={q['question_id']:q for q in read(Path('docs/curriculum/app-migration/question-map.json'))['questions']}; identities={q['question_id']:q for q in read(Path('docs/curriculum/app-migration/implementation-evidence/9D1/authored-identities.json'))['questions']}
 reviews=read(BASE/'source-review.json')['questions']; emitter=Emitter(Schema(ROOT),'scenario9G'); lines=(ROOT/BANK).read_text().splitlines(True); receipts=[];typed=[]
 for n,qid in enumerate(IDS):
  a=next(q for q in actions if q['question_id']==qid); draft=copy.deepcopy(a['proposed_changes']['draft_question']); before=a['original']; review=reviews[n];m=mapping[qid];option_ids=identities[qid]['option_ids_in_authored_order']
  assert review['question_id']==qid and review['verified_on']=='2026-10-16'
  assert len(draft['options'])==len({o['text'] for o in draft['options']})==4
  assert draft['correct']==before['correct'] and draft['id']==before['id'] and draft['concept']==before['concept']
  assert [v['correct'] for v in review['option_verdicts']]==[i==draft['correct'] for i in range(4)]
  for verdict,o in zip(review['option_verdicts'],draft['options']):assert verdict['reason']==o['explanation']
  q={'key':{'question_id':qid,'revision':'scenario-r2'},'concept_id':draft['concept'],'category':draft['category'].lower(),'prompt':rich(draft['prompt']),'image':None,'options':[{'id':oid,'text':rich(o['text']),'image':None} for oid,o in zip(option_ids,draft['options'])],
   'feedback':{'target_sign_code':None,'english_label':None,'correct_option_id':option_ids[draft['correct']],'explanation':rich(draft['explanation']),'option_feedback':[{'option_id':oid,'explanation':rich(o['explanation']),'sign_code':None,'english_label':None,'source_uses':[]} for oid,o in zip(option_ids,draft['options'])]},
   'relationship':{**{k:copy.deepcopy(m[k]) for k in ['primary_lesson_id','related_lesson_ids','reference_ids','source_ids','content_version']},'disposition':'rewrite','source_uses':[]},
   'acceptance':{'eligibility':'accepted','content_review':{'record':origin(BASE/'source-review.json',f'json:/questions/{n}'),'reviewed_on':'2026-10-16'},'description_reviews':[],'delivery_proof':[],'open_holds':[]},'origin':origin(ACTIONS,f'json:/questions/{actions.index(a)}/proposed_changes/draft_question')}
  draft['assessment']=q;current=next(row for row in bank if row['id']==qid)
  assert current in (before,draft),f'Unexpected edits to {qid}'
  bank[bank.index(current)]=draft; call=emitter.emit(q,'AssessmentQuestion',qid)
  options=', '.join('Option('+', '.join(kotlin_string(o[k]) for k in ['text','explanation','image'])+')' for o in draft['options'])
  args=[kotlin_string(draft['id']),kotlin_string(draft['concept']),'Category.'+draft['category'],kotlin_string(draft['prompt']),'listOf('+options+')',str(draft['correct']),kotlin_string(draft['explanation']),str(draft['page']),kotlin_string(draft['source']),kotlin_string(draft['image']),call]
  matches=[i for i,l in enumerate(lines) if l.startswith('Question('+kotlin_string(qid)+',')];assert len(matches)==1
  lines[matches[0]]='Question('+', '.join(args)+'),\n'
  receipts.append({'step':f'9G{n+1}','question_id':qid,'before_revision':'legacy-r1','after_revision':'scenario-r2','content_acceptance':'passed','one_correct_answer':True,'correct_option_id':option_ids[draft['correct']],'all_explanations_reviewed':True,'source_review':str(BASE/'source-review.json')+f'#/questions/{n}','before':before,'after':draft});typed.append(q)
 return {Path('content/questions.json'):dump(bank),BANK:''.join(lines),Path('composeApp/src/commonMain/kotlin/se/korkort/ScenarioCorrections9G.kt'):'package se.korkort\n\n// Generated by tools/apply_scenario_corrections_9g.py.\n'+'\n'.join(f'internal fun {name}(): {kind} = {expression}\n' for name,kind,expression in emitter.functions),BASE/'questions.json':dump({'schema_version':1,'questions':typed}),BASE/'question-acceptance.json':dump({'schema_version':1,'step':'9G','execution_order':IDS,'questions':receipts,'release_acceptance':False,'release_note':'Content corrections accepted; complete app/release acceptance remains 9J–9O. Earlier attempts retain legacy-r1 semantics; no history rewrite.'})}
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--check',action='store_true');args=p.parse_args()
 for path,value in outputs().items():
  if args.check:assert (ROOT/path).read_text()==value,path
  else:(ROOT/path).write_text(value)
 print('9G1–9G8: eight exact corrections, stable IDs and keys, scenario-r2 metadata.')
if __name__=='__main__':main()
